INSERT INTO sites (url, url_raw, title, description, logo, taxonomy, term, status, source, sort) VALUES ('https://pixabay.com/zh/videos', 'https://pixabay.com/zh/videos/', 'Pixabay', '一个老牌的素材站了，Pixabay 也提供数量众多的矢量图、插画、照片等无版权素材', 'wZMwUs.png', '媒体创作', '无版权视频', 'published', 'seed', 0), ('https://videos.pexels.com', 'https://videos.pexels.com', 'pexels', 'Pexels 是集大成的素材站，无版权的图片和视频它都有，还集成了别的站点的资源，种类和数量都很可观。', 'videos.pexels.com.ico', '媒体创作', '无版权视频', 'published', 'seed', 1), ('https://www.openfootage.net', 'https://www.openfootage.net', 'OpenFootage', 'OpenFootage在其网站上提供了很好的自然，延时和抽象视频选择。可以免费下载这些视频的低分辨率版本', 'www.openfootage.net.ico', '媒体创作', '无版权视频', 'published', 'seed', 2), ('http://www.movietools.info', 'http://www.movietools.info', 'Movie Tools', '在MovieTools，可以下载免费的循环和背景，用于自己的非商业视频', 'www.movietools.info.ico', '媒体创作', '无版权视频', 'published', 'seed', 3), ('https://www.pond5.com/stock-footage', 'https://www.pond5.com/stock-footage/', 'Pond5 Free Video Footage', 'Pond5对他们的大部分镜头收费，但他们也提供免费的旧镜头。', 'www.pond5.com.ico', '媒体创作', '无版权视频', 'published', 'seed', 4), ('http://mitchmartinez.com/free-4k-red-epic-stock-footage', 'http://mitchmartinez.com/free-4k-red-epic-stock-footage', 'Mitch Martinez', '如果正在搜索4K素材，请查看此站点。', 'mitchmartinez.com.ico', '媒体创作', '无版权视频', 'published', 'seed', 5), ('http://www.beachfrontbroll.com', 'http://www.beachfrontbroll.com', 'Beachfront B-Roll', 'Beachfront B-Roll是一个视频博客，提供高清素材和动画背景。', 'www.beachfrontbroll.com.ico', '媒体创作', '无版权视频', 'published', 'seed', 6), ('https://www.splitshire.com', 'https://www.splitshire.com', 'SplitShire', 'SplitShire是网页设计师Daniel Nanescu的心血结晶，他想与全世界分享他的免费图片和视频集', 'www.splitshire.com.ico', '媒体创作', '无版权视频', 'published', 'seed', 7), ('http://www.coverr.co', 'http://www.coverr.co', 'coverr', 'Coverr网站就是纯粹为我们提供免费视频下载的站点，网站为我们做了详细的视频分类，每周一会更新7个视频', 'www.coverr.co.ico', '媒体创作', '无版权视频', 'published', 'seed', 8), ('https://vimeo.com/groups/freehd', 'https://vimeo.com/groups/freehd/', 'Free HD Stock Footage on Vimeo', '这个Vimeo组有258个免费视频