INSERT INTO sites (url, url_raw, title, description, logo, taxonomy, term, status, source, sort) VALUES ('https://www.dji.com/cn', 'https://www.dji.com/cn', '大疆无人机官网', '大疆无人机官网', 'd9dbbvkdjhk.png', '媒体创作', '无人机航拍', 'published', 'seed', 0), ('https://support.dji.com/help/content?customId=zh-cn03400006730&spaceId=34&re=CN&lang=zh-CN', 'https://support.dji.com/help/content?customId=zh-cn03400006730&spaceId=34&re=CN&lang=zh-CN', '无人机实名登记步骤', '了解如何通过 UOM app 和 UOM 官网进行实名登记，登记时需要填写的信息，如何进行注销登记，以及抢注申诉需要准备的材料，请参考本篇内容获取帮助', 'https://repair.djicdn.com/static/modal/favicon.ico', '媒体创作', '无人机航拍', 'published', 'seed', 1), ('https://uom.caac.gov.cn', 'https://uom.caac.gov.cn/', 'UOM APP', '民用无人机航空器管理平台', 'https://uom.caac.gov.cn/login/img/portal-logo.675a28a6.png', '媒体创作', '无人机航拍', 'published', 'seed', 2), ('https://www.qingzhicheng.com', 'https://www.qingzhicheng.com/', '起航无人机行业资质服务平台', '无人机资质证书,无人机运营许可证,无人机运营合格证,无人机驾驶,aopa无人机驾驶证,alpa无人机驾驶证,asfc无人机证书含金量,无人机企业甲级资质办理等。', 'https://www.qingzhicheng.com/uploads/allimg/20240308/1-24030Q13SM20.png', '媒体创作', '无人机航拍', 'published', 'seed', 3), ('https://dronelife.com', 'https://dronelife.com/', 'Dronelife - 无人机行业新闻的可靠来源 --- Dronelife - The Trusted Source for Drone Industry News', '商用无人机市场新闻', 'https://dronelife.com/wp-content/uploads/2018/06/cropped-dronelife-icon-500x500-45x45.png', '媒体创作', '无人机航拍', 'published', 'seed', 4), ('https://www.dronebao.com', 'https://www.dronebao.com/', '航拍保', '航拍保的无人机保险覆盖全面：人机砸到人、无人机炸机、无人机禁飞、平安 无人机保险 、悬挂设备等财产损失、第三者责任、飞手责任、飞手个人意外皆可承保。', 'https://www.dronebao.com/favicon.ico', '媒体创作', '无人机航拍', 'published', 'seed', 5), ('https://www.hangpai.org', 'https://www.hangpai.org/', '航拍网', '航拍网-科技,低空,文旅,数码,无人机,航拍,旅行,摄影,评测;汇集优秀航拍摄影科技数码创作者及作品,科技数码产品资讯 ,评测;提供低空经济所涉及无人驾驶,数字低空,绿色能源全生态链服务解决方案', 'https://www.hangpai.org/favicon.ico', '媒体创作', '无人机航拍', 'published', 'seed', 6), ('https://www.iflight.cn', 'https://www.iflight.cn/', 'iFlight翼飞官方商城', 'iFlight翼飞智能科技，以创新精神引领FPV穿越机领域，打造高品质的穿越机第一视角飞行影像、竞技及娱乐体验平台。我们专注于设计、研发、生产至销售的全链条，致力于为